import { expect, test } from './fixtures';
import { LoginPage } from './pages/login';
import { TopBar } from './pages/shop';

test.describe('TC-01: Login with a valid and an invalid password', () => {
  test('login with a wrong and then a correct password', async ({ page, customer }) => {
    const login = new LoginPage(page);
    const topBar = new TopBar(page);
    const wrongPassword = `${customer.password}x`;

    await test.step('1. Open the login page', async () => {
      await login.goto();
      await expect(login.heading).toBeVisible();
      await expect(login.emailField).toBeVisible();
      await expect(login.passwordField).toBeVisible();
      await expect(login.loginButton).toBeVisible();
    });

    await test.step('2. Log in with the wrong password', async () => {
      await login.login(customer.email, wrongPassword);
      await expect(login.invalidCredentialsError).toBeVisible();
      await expect(page).toHaveURL(/#\/login/);
    });

    await test.step('3. The account menu shows Login and not the email', async () => {
      await topBar.openAccountMenu();
      await expect(topBar.accountMenu.getByRole('menuitem').filter({ hasText: 'Login' })).toBeVisible();
      await expect(topBar.accountMenu).not.toContainText(customer.email);
    });

    await test.step('4. Log in with the correct password', async () => {
      await page.keyboard.press('Escape');
      await login.login(customer.email, customer.password);
      await expect(page).toHaveURL(/#\/search/);
    });

    await test.step('5. The account menu shows the email and Logout', async () => {
      await topBar.openAccountMenu();
      await expect(topBar.accountMenu).toContainText(customer.email);
      await expect(topBar.accountMenu.getByRole('menuitem', { name: 'Logout', exact: true })).toBeVisible();
    });
  });
});

