import { expect, test } from './fixtures';
import { BasketPage, ProductListPage, TopBar } from './pages/shop';
import { PRODUCTS } from './helpers/test-data';

test.describe('TC-02: Add a product to the basket', () => {
  test('add one product and check the basket', async ({ loggedInPage: page }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const product = PRODUCTS.eggfruit;

    await test.step('1. The product list shows the product and an empty basket', async () => {
      await products.goto();
      await products.expectProductTile(product.name, product.price);
      await topBar.expectBasketCounter(0);
    });

    await test.step('2. Add the product to the basket', async () => {
      await products.addToBasket(product.name);
      await products.expectMessage(`Placed ${product.name} into basket.`);
      await topBar.expectBasketCounter(1);
    });

    await test.step('3. The basket shows one row with the product', async () => {
      await topBar.openBasket();
      await basket.expectRow(product.name, 1);
      await expect(basket.row(product.name)).toContainText(product.price);
    });

    await test.step('4. The basket total is the price of the product', async () => {
      await basket.expectTotal(product.price);
    });
  });
});

