import { test } from './fixtures';
import { BasketPage, ProductListPage, TopBar } from './pages/shop';
import { PRODUCTS } from './helpers/test-data';

test.describe('TC-03: Change the quantity and remove a product in the basket', () => {
  test('change the quantity and remove product A', async ({ loggedInPage: page }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const productA = PRODUCTS.raspberry;
    const productB = PRODUCTS.eggfruit;

    // Precondition 3: the basket holds product A and product B with quantity 1.
    await products.search(productA.name);
    await products.addToBasket(productA.name);
    await products.search(productB.name);
    await products.addToBasket(productB.name);
    await topBar.expectBasketCounter(2);

    await test.step('1. The basket shows both products and the total 13.98¤', async () => {
      await topBar.openBasket();
      await basket.expectRow(productA.name, 1);
      await basket.expectRow(productB.name, 1);
      await basket.expectTotal('13.98¤');
      await topBar.expectBasketCounter(2);
    });

    await test.step('2. Plus button on product A: quantity 2, total 18.97¤', async () => {
      await basket.increase(productA.name).click();
      await basket.expectRow(productA.name, 2);
      await basket.expectTotal('18.97¤');
      await topBar.expectBasketCounter(3);
    });

    await test.step('3. Minus button on product A: quantity 1, total 13.98¤', async () => {
      await basket.decrease(productA.name).click();
      await basket.expectRow(productA.name, 1);
      await basket.expectTotal('13.98¤');
      await topBar.expectBasketCounter(2);
    });

    await test.step('4. Minus button on product A again: quantity stays 1', async () => {
      await basket.decrease(productA.name).click();
      await basket.expectRow(productA.name, 1);
      await basket.expectTotal('13.98¤');
    });

    await test.step('5. Trash button on product A: only product B stays', async () => {
      await basket.remove(productA.name).click();
      await basket.expectNoRow(productA.name);
      await basket.expectRow(productB.name, 1);
      await basket.expectTotal('8.99¤');
      await topBar.expectBasketCounter(1);
    });
  });
});

