import { expect, test } from './fixtures';
import { BasketPage, ProductListPage, TopBar } from './pages/shop';
import { PRODUCTS, PURCHASE_LIMIT_MESSAGE } from './helpers/test-data';

test.describe('TC-04: Purchase limit for one product', () => {
  test('the basket stops at 5 items of one product', async ({ loggedInPage: page }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const product = PRODUCTS.apple;

    await test.step('1. Add the product to the basket from the product list', async () => {
      await products.goto();
      await products.addToBasket(product.name);
      await topBar.expectBasketCounter(1);
    });

    await test.step('2. Plus button until the quantity is 5: total 9.95¤, no error', async () => {
      await topBar.openBasket();
      for (let quantity = 2; quantity <= 5; quantity++) {
        await basket.increase(product.name).click();
        await basket.expectRow(product.name, quantity);
      }
      await basket.expectTotal('9.95¤');
      await expect(page.getByText(PURCHASE_LIMIT_MESSAGE)).toHaveCount(0);
    });

    await test.step('3. Plus button once more: the error shows', async () => {
      await basket.increase(product.name).click();
      await products.expectMessage(PURCHASE_LIMIT_MESSAGE);
    });

    await test.step('4. The product keeps quantity 5 and the total 9.95¤', async () => {
      await basket.expectRow(product.name, 5);
      await basket.expectTotal('9.95¤');
      await topBar.expectBasketCounter(5);
    });

    await test.step('5. Add to Basket from the product list: the error shows, counter stays 5', async () => {
      await products.goto();
      await products.clickAddToBasket(product.name);
      await products.expectMessage(PURCHASE_LIMIT_MESSAGE);
      await topBar.expectBasketCounter(5);
    });
  });
});

