import { expect, test } from './fixtures';
import { addSavedAddress, addSavedCard } from './helpers/api';
import { couponCode } from './helpers/coupon';
import { DELIVERY, INVALID_COUPON, PRODUCTS } from './helpers/test-data';
import { AddressPage, DeliveryPage, OrderSummaryPage, PaymentPage } from './pages/checkout';
import { BasketPage, ProductListPage, TopBar } from './pages/shop';

test.describe('TC-06: Invalid coupon and expired coupon', () => {
  test('neither an invalid code nor an expired coupon gives a discount', async ({ loggedInPage: page, customer, request }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const addressPage = new AddressPage(page);
    const deliveryPage = new DeliveryPage(page);
    const paymentPage = new PaymentPage(page);
    const summary = new OrderSummaryPage(page);
    const product = PRODUCTS.eggfruit;

    // Preconditions 3 and 4: saved address and card, basket with product quantity 2.
    await addSavedAddress(request, customer.token);
    await addSavedCard(request, customer.token);
    await products.goto();
    await products.addToBasket(product.name);
    await products.addToBasket(product.name);
    await topBar.expectBasketCounter(2);

    await test.step('1. Checkout, select the saved address and continue: delivery page opens', async () => {
      await topBar.openBasket();
      await basket.checkoutButton.click();
      await addressPage.expectOpen();
      await addressPage.selectSavedAddress();
      await addressPage.continue();
      await deliveryPage.expectOpen();
    });

    await test.step('2. Select One Day Delivery and continue: payment page opens', async () => {
      await deliveryPage.select(DELIVERY.oneDay.name);
      await deliveryPage.continue();
      await paymentPage.expectOpen();
    });

    await test.step('3. Redeem the invalid code: the error shows, no discount', async () => {
