import { expect, test } from './fixtures';
import { addMoneyToWallet, addSavedAddress, addSavedCard } from './helpers/api';
import { DELIVERY, PRODUCTS } from './helpers/test-data';
import { AddressPage, DeliveryPage, OrderCompletionPage, OrderSummaryPage, PaymentPage } from './pages/checkout';
import { OrderHistoryPage, WalletPage } from './pages/account';
import { BasketPage, ProductListPage, TopBar } from './pages/shop';

test.describe('TC-08: Payment with the wallet', () => {
  test('the wallet cannot pay a short balance and pays the exact total', async ({ loggedInPage: page, customer, request }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const addressPage = new AddressPage(page);
    const deliveryPage = new DeliveryPage(page);
    const paymentPage = new PaymentPage(page);
    const summary = new OrderSummaryPage(page);
    const completion = new OrderCompletionPage(page);
    const history = new OrderHistoryPage(page);
    const wallet = new WalletPage(page);
    const product = PRODUCTS.eggfruit;
    let orderId = '';

    // Preconditions 3, 4 and 5: saved address and card, basket with product quantity 1, wallet 5.00¤.
    const cardId = await addSavedCard(request, customer.token);
    await addSavedAddress(request, customer.token);
    await addMoneyToWallet(request, customer.token, cardId, 5);
    await products.goto();
    await products.addToBasket(product.name);
    await topBar.expectBasketCounter(1);

    // Part 1: the wallet holds less than the order total.
    await test.step('1. Checkout, select the saved address and continue: delivery page opens', async () => {
      await topBar.openBasket();
      await basket.checkoutButton.click();
      await addressPage.expectOpen();
      await addressPage.selectSavedAddress();
      await addressPage.continue();
      await deliveryPage.expectOpen();
    });

    await test.step('2. Select Standard Delivery and continue: wallet balance 5.00 and the pay button 8.99¤', async () => {
      await deliveryPage.select(DELIVERY.standard.name);
      await deliveryPage.continue();
      await paymentPage.expectOpen();
      await expect(page.getByText('Wallet Balance')).toBeVisible();
      await expect(page.locator('body')).toContainText('5.00');
      await expect(paymentPage.walletPayButton('8.99¤')).toBeVisible();
    });

    await test.step('3. The pay button 8.99¤ is disabled', async () => {
      await expect(paymentPage.walletPayButton('8.99¤')).toBeDisabled();
    });

    await test.step('4. Order history shows no orders', async () => {
      await topBar.openOrdersAndPaymentItem('Order History');
      await history.expectEmpty();
    });

    await test.step('5. Digital wallet shows the balance 5.00', async () => {
      await topBar.openOrdersAndPaymentItem('Digital Wallet');
      await wallet.expectBalance('5.00');
    });

    // Part 2: the wallet holds exactly the order total.
    await test.step('6. Add 3.99 with the saved card; checkout to payment: pay button 8.99¤ is enabled', async () => {
      await addMoneyToWallet(request, customer.token, cardId, 3.99);
      await page.goto('/#/basket');
      await basket.checkoutButton.click();
      await addressPage.expectOpen();
      await addressPage.selectSavedAddress();
      await addressPage.continue();
      await deliveryPage.expectOpen();
      await deliveryPage.select(DELIVERY.standard.name);
      await deliveryPage.continue();
      await paymentPage.expectOpen();
      await expect(page.locator('body')).toContainText('8.99');
      await expect(paymentPage.walletPayButton('8.99¤')).toBeEnabled();
    });

    await test.step('7. Pay with the wallet: order summary shows Digital Wallet and 8.99¤', async () => {
      await paymentPage.walletPayButton('8.99¤').click();
      await summary.expectOpen();
      await expect(page.getByText('Digital Wallet').first()).toBeVisible();
      await expect(summary.line('Total Price')).toContainText('8.99¤');
    });

    await test.step('8. Place the order: the confirmation shows the thank you text', async () => {
      await summary.placeOrder();
      orderId = await completion.expectOpen();
    });

