import { expect, type Page } from '@playwright/test';
import { escapeRegExp, price } from '../helpers/money';

/** The page `Order History`, opened from the account menu. */
export class OrderHistoryPage {
  constructor(private readonly page: Page) {}

  async expectOpen(): Promise<void> {
    await expect(this.page).toHaveURL(/#\/order-history/);
  }

  async expectEmpty(): Promise<void> {
    await this.expectOpen();
    await expect(this.page.getByText('You have not placed any orders yet.')).toBeVisible();
  }

  /** Each order card has one `Track Your Order` button. */
  async expectOrderCount(count: number): Promise<void> {
    await expect(this.page.getByRole('button', { name: 'Track Your Order' })).toHaveCount(count);
  }

  /** The order card shows the order ID and the total price. */
  async expectOrder(orderId: string, total: string): Promise<void> {
    await this.expectOpen();
    await expect(this.page.getByText(orderId).first()).toBeVisible();
    await expect(this.page.locator('body')).toContainText(new RegExp(`Total Price\\s*${escapeRegExp(total)}`));
  }

  /** The product row shows the name, the quantity and the price of the product. */
  async expectProduct(name: string, quantity: number, unitPrice: string): Promise<void> {
    const row = this.page.getByRole('row').filter({ hasText: name });
    await expect(row).toContainText(price(unitPrice));
    await expect(row.getByRole('cell', { name: String(quantity), exact: true })).toBeVisible();
  }
}

/** The page `Digital Wallet`, opened from the account menu. */
export class WalletPage {
  constructor(private readonly page: Page) {}

  async expectBalance(balance: string): Promise<void> {
    await expect(this.page.getByText(new RegExp(`Wallet Balance\\s*${escapeRegExp(balance)}\\b`))).toBeVisible();
  }
}

