1125	/**
1126	 * Builds a coupon code as described in test-cases/README.md:
1127	 * Z85 encoding of `<MMM><YY>-<NN>`.
1128	 *
1129	 * @param discount discount in percent, for example 10
1130	 * @param monthsAgo 0 for the current month, 1 for the previous month
1131	 * @param now date of the machine that runs the test
1132	 */
1133	export function couponCode(discount: number, monthsAgo = 0, now = new Date()): string {
1134	  const month = new Date(now.getFullYear(), now.getMonth() - monthsAgo, 1);
1135	  const mmm = MONTHS[month.getMonth()];
1136	  const yy = String(month.getFullYear() % 100).padStart(2, '0');
1137	  const nn = String(discount).padStart(2, '0');
1138	  const code = z85.encode(`${mmm}${yy}-${nn}`);
1139	  if (code === null) {
1140	    throw new Error(`Coupon text must be a multiple of 4 bytes for Z85: ${mmm}${yy}-${nn}`);
1141	  }
1142	  return code;
1143	}
