import { test as base, expect, type Page } from '@playwright/test';
import { createCustomer, type Customer } from './helpers/api';
import { LoginPage } from './pages/login';
import { dismissCookieBanner } from './pages/shop';

type Fixtures = {
  /** A new normal customer account, created through the API before the test. */
  customer: Customer;
  /** A page where the customer is logged in through the login form. */
  loggedInPage: Page;
};

export const test = base.extend<Fixtures>({
  // The cookie banner hides itself after this cookie, see test-cases/README.md.
  context: async ({ context, baseURL }, use) => {
    await context.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: baseURL }]);
    await use(context);
  },

  customer: async ({ request }, use) => {
    await use(await createCustomer(request));
  },

  loggedInPage: async ({ page, customer }, use) => {
    const login = new LoginPage(page);
    await login.goto();
    await login.login(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search/);
    await dismissCookieBanner(page);
    await use(page);
  },
});

export { expect };

