test.describe('TC-07: Order with a card, from basket to order history', () => {
  test('order two products with a card and find the order in the history', async ({ loggedInPage: page, customer, request }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const addressPage = new AddressPage(page);
    const deliveryPage = new DeliveryPage(page);
    const paymentPage = new PaymentPage(page);
    const summary = new OrderSummaryPage(page);
    const completion = new OrderCompletionPage(page);
    const confirmationTotals = new ConfirmationTotals(page);
    const history = new OrderHistoryPage(page);
    const productA = PRODUCTS.eggfruit;
    const productB = PRODUCTS.carrot;
    let orderId = '';

    // Preconditions 3 and 4: saved address and card; the basket is empty.
    await addSavedAddress(request, customer.token);
    await addSavedCard(request, customer.token);

    await test.step('1. Add product A two times and product B one time: counter 3', async () => {
      await products.search(productA.name);
      await products.addToBasket(productA.name);
      await products.addToBasket(productA.name);
      await products.search(productB.name);
      await products.addToBasket(productB.name);
      await topBar.expectBasketCounter(3);
    });

    await test.step('2. The basket shows both products and the total 20.97¤', async () => {
      await topBar.openBasket();
      await basket.expectRow(productA.name, 2);
      await basket.expectRow(productB.name, 1);
      await basket.expectTotal('20.97¤');
    });

    await test.step('3. Checkout, select the saved address and continue: delivery page opens', async () => {
      await basket.checkoutButton.click();
      await addressPage.expectOpen();
      await addressPage.selectSavedAddress();
      await addressPage.continue();
      await deliveryPage.expectOpen();
    });

    await test.step('4. Select One Day Delivery and continue: payment page opens', async () => {
      await deliveryPage.select(DELIVERY.oneDay.name);
      await deliveryPage.continue();
      await paymentPage.expectOpen();
    });

    await test.step('5. Redeem the coupon of the current month', async () => {
      await paymentPage.redeemCoupon(couponCode(10));
      await expect(page.getByText('Your discount of 10% will be applied during checkout.')).toBeVisible();
    });

    await test.step('6. Select the saved card and continue: order summary with 19.86¤', async () => {
      await paymentPage.selectSavedCard();
      await paymentPage.continue();
      await summary.expectOpen();
      await expect(page.getByText('Test Customer').first()).toBeVisible();
      await summary.expectTotals('20.97¤', '0.99¤', '2.10¤', '19.86¤');
    });

    await test.step('7. Place the order: the confirmation page opens', async () => {
      await summary.placeOrder();
      orderId = await completion.expectOpen();
      expect(orderId).not.toBe('');
    });

    await test.step('8. The confirmation shows both products and the totals', async () => {
      await expect(page.getByText(productA.name).first()).toBeVisible();
      await expect(page.getByText(productB.name).first()).toBeVisible();
      await confirmationTotals.expectTotals('20.97¤', '0.99¤', '2.10¤', '19.86¤');
