test.describe('TC-08: Payment with the wallet', () => {
  test('the wallet cannot pay a short balance and pays the exact total', async ({ loggedInPage: page, customer, request }) => {
    const products = new ProductListPage(page);
    const topBar = new TopBar(page);
    const basket = new BasketPage(page);
    const addressPage = new AddressPage(page);
    const deliveryPage = new DeliveryPage(page);
    const paymentPage = new PaymentPage(page);
    const summary = new OrderSummaryPage(page);
    const completion = new OrderCompletionPage(page);
    const history = new OrderHistoryPage(page);
    const wallet = new WalletPage(page);
    const product = PRODUCTS.eggfruit;
    let orderId = '';

    // Preconditions 3, 4 and 5: saved address and card, basket with product quantity 1, wallet 5.00¤.
    const cardId = await addSavedCard(request, customer.token);
    await addSavedAddress(request, customer.token);
    await addMoneyToWallet(request, customer.token, cardId, 5);
    await products.goto();
    await products.addToBasket(product.name);
    await topBar.expectBasketCounter(1);

    // Part 1: the wallet holds less than the order total.
    await test.step('1. Checkout, select the saved address and continue: delivery page opens', async () => {
      await topBar.openBasket();
      await basket.checkoutButton.click();
      await addressPage.expectOpen();
      await addressPage.selectSavedAddress();
      await addressPage.continue();
      await deliveryPage.expectOpen();
    });

    await test.step('2. Select Standard Delivery and continue: wallet balance 5.00 and the pay button 8.99¤', async () => {
