      await expect(page.locator('body')).toContainText('5.00');
      await expect(paymentPage.walletPayButton('8.99¤')).toBeVisible();
    });

    await test.step('3. The pay button 8.99¤ is disabled', async () => {
      await expect(paymentPage.walletPayButton('8.99¤')).toBeDisabled();
    });

    await test.step('4. Order history shows no orders', async () => {
      await topBar.openOrdersAndPaymentItem('Order History');
      await history.expectEmpty();
    });

    await test.step('5. Digital wallet shows the balance 5.00', async () => {
      await topBar.openOrdersAndPaymentItem('Digital Wallet');
      await wallet.expectBalance('5.00');
    });

    // Part 2: the wallet holds exactly the order total.
