import { randomUUID } from 'node:crypto';
import type { APIRequestContext } from '@playwright/test';
import { SAVED_ADDRESS, SAVED_CARD } from './test-data';

export const PASSWORD = 'Passw0rd!tc01';

export interface Customer {
  email: string;
  password: string;
  token: string;
}

/** Creates a normal customer account with a unique email and logs it in through the API. */
export async function createCustomer(request: APIRequestContext): Promise<Customer> {
  const email = `tc-${Date.now()}-${randomUUID().slice(0, 8)}@example.test`;

  const registered = await request.post('/api/Users/', {
    data: {
      email,
      password: PASSWORD,
      passwordRepeat: PASSWORD,
      securityQuestion: { id: 1, question: 'Your eldest siblings middle name?' },
      securityAnswer: 'test',
    },
  });
  if (!registered.ok()) {
    throw new Error(`Registration failed: ${registered.status()} ${await registered.text()}`);
  }

  const login = await request.post('/rest/user/login', { data: { email, password: PASSWORD } });
  if (!login.ok()) {
    throw new Error(`API login failed: ${login.status()} ${await login.text()}`);
  }
  const body = (await login.json()) as { authentication: { token: string } };
  return { email, password: PASSWORD, token: body.authentication.token };
}

/** Saves the address from test-cases/README.md for the customer. */
export async function addSavedAddress(request: APIRequestContext, token: string): Promise<void> {
  const response = await request.post('/api/Addresss/', {
    headers: { Authorization: `Bearer ${token}` },
    data: {
      fullName: SAVED_ADDRESS.name,
      mobileNum: Number(SAVED_ADDRESS.mobileNumber),
      zipCode: SAVED_ADDRESS.zip,
      streetAddress: SAVED_ADDRESS.address,
      city: SAVED_ADDRESS.city,
      state: SAVED_ADDRESS.state,
      country: SAVED_ADDRESS.country,
    },
  });
  if (!response.ok()) {
    throw new Error(`Saving the address failed: ${response.status()} ${await response.text()}`);
  }
}

/** Saves the card from test-cases/README.md for the customer and returns its ID. */
export async function addSavedCard(request: APIRequestContext, token: string): Promise<string> {
  const response = await request.post('/api/Cards/', {
    headers: { Authorization: `Bearer ${token}` },
    data: {
      fullName: SAVED_CARD.name,
      cardNum: Number(SAVED_CARD.number),
      expMonth: SAVED_CARD.expiryMonth,
      expYear: SAVED_CARD.expiryYear,
    },
  });
  if (!response.ok()) {
    throw new Error(`Saving the card failed: ${response.status()} ${await response.text()}`);
  }
  const body = (await response.json()) as { data: { id: number } };
  return String(body.data.id);
}

/** Adds money to the wallet with the saved card. The shop endpoint adds the amount to the balance. */
export async function addMoneyToWallet(
  request: APIRequestContext,
  token: string,
  cardId: string,
  amount: number,
): Promise<void> {
  const response = await request.put('/rest/wallet/balance', {
    headers: { Authorization: `Bearer ${token}` },
    data: { paymentId: cardId, balance: amount },
  });
  if (!response.ok()) {
    throw new Error(`Adding money to the wallet failed: ${response.status()} ${await response.text()}`);
  }
}

