import * as z85 from 'z85';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/**
 * Builds a coupon code as described in test-cases/README.md:
 * Z85 encoding of `<MMM><YY>-<NN>`.
 *
 * @param discount discount in percent, for example 10
 * @param monthsAgo 0 for the current month, 1 for the previous month
 * @param now date of the machine that runs the test
 */
export function couponCode(discount: number, monthsAgo = 0, now = new Date()): string {
  const month = new Date(now.getFullYear(), now.getMonth() - monthsAgo, 1);
  const mmm = MONTHS[month.getMonth()];
  const yy = String(month.getFullYear() % 100).padStart(2, '0');
  const nn = String(discount).padStart(2, '0');
  const code = z85.encode(`${mmm}${yy}-${nn}`);
  if (code === null) {
    throw new Error(`Coupon text must be a multiple of 4 bytes for Z85: ${mmm}${yy}-${nn}`);
  }
  return code;
}

