/** Escapes text so it can be used inside a RegExp. */
export function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Matches a price such as `8.99¤` anywhere in the text of an element. */
export function price(value: string): RegExp {
  return new RegExp(escapeRegExp(value));
}

/** Matches `Total Price: 8.99¤` in the text of an element. */
export function totalPrice(value: string): RegExp {
  return new RegExp(`Total Price:\\s*${escapeRegExp(value)}`);
}

