// Experiments for the audit. Each test applies a WRONG action or a wrong state
// and then runs the original assertions. A passing experiment = the assertion is vacuous.
const P = '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests';
import { expect, test } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/fixtures';
import { BasketPage, ProductListPage, TopBar } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/pages/shop';
import { PRODUCTS, PURCHASE_LIMIT_MESSAGE, DELIVERY, INVALID_COUPON } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/helpers/test-data';
import { addMoneyToWallet, addSavedAddress, addSavedCard } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/helpers/api';
import { couponCode } from '/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/desk-r/tests/helpers/coupon';
