test('E1 TC-04 step 5 without clicking Add to Basket', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const product = PRODUCTS.apple;
  await products.goto();
  await products.addToBasket(product.name);
  await topBar.openBasket();
  for (let q = 2; q <= 5; q++) {
    await basket.increase(product.name).click();
    await basket.expectRow(product.name, q);
  }
  await basket.increase(product.name).click();
  await products.expectMessage(PURCHASE_LIMIT_MESSAGE);
  await basket.expectRow(product.name, 5);
  await basket.expectTotal('9.95¤');
  await topBar.expectBasketCounter(5);
  // step 5, but NO click on Add to Basket
  await products.goto();
  await products.expectMessage(PURCHASE_LIMIT_MESSAGE);
  await topBar.expectBasketCounter(5);
});

test('E2 TC-07 step 9 assertions with a NON-empty basket', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  await products.search(PRODUCTS.eggfruit.name);
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await products.search(PRODUCTS.carrot.name);
  await products.addToBasket(PRODUCTS.carrot.name);
  await topBar.openBasket();
  await basket.expectNoRow(PRODUCTS.eggfruit.name);
  await basket.expectNoRow(PRODUCTS.carrot.name);
  await expect(basket.checkoutButton).toBeDisabled({ timeout: 1000 });
});

test('E2b TC-07 step 9 row checks only, NON-empty basket', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  await products.search(PRODUCTS.eggfruit.name);
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.expectNoRow(PRODUCTS.eggfruit.name);
});

test('E3 TC-03 step 4 assertions after clicking PLUS instead of minus', async ({ loggedInPage: page }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const a = PRODUCTS.raspberry, b = PRODUCTS.eggfruit;
  await products.search(a.name);
  await products.addToBasket(a.name);
  await products.search(b.name);
  await products.addToBasket(b.name);
  await topBar.openBasket();
  await basket.expectRow(a.name, 1);
