  await basket.increase(a.name).click();
  await basket.expectRow(a.name, 1);
  await basket.expectTotal('13.98¤');
});

test('E4 TC-08 step 6 balance check with balance 5.00 (no top-up)', async ({ loggedInPage: page, customer, request }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const cardId = await addSavedCard(request, customer.token);
  await addSavedAddress(request, customer.token);
  await addMoneyToWallet(request, customer.token, cardId, 5);
  await products.goto();
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.checkoutButton.click();
  await addressPage.selectSavedAddress();
  await addressPage.continue();
  await deliveryPage.select(DELIVERY.standard.name);
  await deliveryPage.continue();
  await paymentPage.expectOpen();
  await expect(page.locator('body')).toContainText('8.99');
});

test('E5 TC-06 step 4 assertions after redeeming a VALID coupon', async ({ loggedInPage: page, customer, request }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  await addSavedAddress(request, customer.token);
  await addSavedCard(request, customer.token);
  await products.goto();
  await products.addToBasket(PRODUCTS.eggfruit.name);
  await topBar.openBasket();
  await basket.checkoutButton.click();
  await addressPage.selectSavedAddress();
  await addressPage.continue();
  await deliveryPage.select(DELIVERY.oneDay.name);
  await deliveryPage.continue();
  await paymentPage.expectOpen();
  await paymentPage.redeemCoupon(INVALID_COUPON);
  await expect(page.getByText('Invalid coupon.')).toBeVisible();
  // step 4 with the CURRENT (valid) coupon instead of the expired one
  await paymentPage.couponField.fill(couponCode(10));
  await paymentPage.redeemButton.click();
  await expect(page.getByText('Invalid coupon.')).toBeVisible();
  await expect(page.getByText('Your discount of')).toHaveCount(0);
});

